glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
out vec2 lightuv;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
vec4 ComputeScreenPos(vec4 positionCS)
{
    vec4 o = positionCS * 0.5;
    float flipped = 1.0;
    o.xy = vec2(o.x, o.y * flipped) + o.w;
    o.zw = positionCS.zw;
    return o;
}
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  #if USE_LIGHTMAP
    lightuv = ComputeScreenPos(pos).xy;
  #endif
  gl_Position = pos;
}

glsl3.frag:
  precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
  in vec4 v_color;
  #if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
  #endif
#if USE_LIGHTMAP
  in vec2 lightuv;
  uniform sampler2D lightmap;
  uniform SpriteLitBlock {
      vec4 ambient;
  };
  vec3 getLight(vec4 light) {
    return light.rgb * light.a ;
  }
#endif
  void main () {
    vec4 o = vec4(1.0);
    vec4 diffuse = vec4(1, 1, 1, 1);
    #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    diffuse.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    diffuse.a *= texture_tmp.a;
  #else
    diffuse *= texture_tmp;
  #endif
    #endif
    #if USE_LIGHTMAP
      vec4 lightmapColor = vec4(1.0);
  vec4 lightmap_tmp = texture(lightmap, lightuv);
  #if CC_USE_ALPHA_ATLAS_lightmap
      lightmap_tmp.a *= texture(lightmap, lightuv + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    lightmapColor.rgb *= (lightmap_tmp.rgb * lightmap_tmp.rgb);
    lightmapColor.a *= lightmap_tmp.a;
  #else
    lightmapColor *= lightmap_tmp;
  #endif
      vec3 finalLight = getLight(lightmapColor) * 3.0 + getLight(ambient);
      o.rgb = diffuse.rgb * finalLight;
      o.a = diffuse.a;
    #else
      o.rgb = diffuse.rgb;
      o.a = diffuse.a;
    #endif
    o.rgb += (1.0 - v_color.rgb);
    o.a *= v_color.a;
    ALPHA_TEST(o);
    #if USE_BGRA
      gl_FragColor = o.bgra;
    #else
      gl_FragColor = o.rgba;
    #endif
  }

